package corpus.safecast

fun textAndRecord(value: Any, record: () -> Unit): String? = if (value is String) {
    record()
    value
} else null

package corpus.safecast

class Holder(val item: Any)
fun heldText(holder: Holder): Any? = if (holder.item is String) holder.item else null
